#!/bin/sh
# SPDX-License-Identifier: GPL-2.0-or-later
# Generate or verify the ABI identity headers and the canonical bridge copies
# at their host and Linux consumers.
set -eu

ROOT_DIR=$(CDPATH= cd -- "$(dirname -- "$0")/../../.." && pwd)
ABI_DIR="$ROOT_DIR/kernel/common/abi"
IDENTITY_PATH="$ABI_DIR/identity.env"
PUBLIC_IDENTITY_PATH="$ROOT_DIR/darwin/api/abi/identity.env"
PUBLIC_IDENTITY_HEADER="$ROOT_DIR/darwin/api/include/uml/abi_identity.h"
HOST_DIR="$ROOT_DIR/darwin/include"
KERNEL_SOURCE=''
VERIFY=0

fail()
{
	printf '%s\n' "kernel/common/abi/sync.sh: $*" >&2
	exit 1
}

usage()
{
	cat <<'EOF'
Usage: kernel/common/abi/sync.sh [--host-dir PATH]
       [--kernel-source PATH] [--verify]

Without --verify, write the identity headers generated from each domain's
identity.env and copy the canonical bridge headers to the requested
destinations. With --verify, require every destination to be byte-identical
to what a write would produce.
EOF
}

while [ "$#" -gt 0 ]; do
	case "$1" in
	--host-dir)
		[ "$#" -ge 2 ] || fail "--host-dir requires a path"
		HOST_DIR=$2
		shift 2
		;;
	--kernel-source)
		[ "$#" -ge 2 ] || fail "--kernel-source requires a path"
		KERNEL_SOURCE=$2
		shift 2
		;;
	--verify)
		VERIFY=1
		shift
		;;
	-h|--help)
		usage
		exit 0
		;;
	*)
		fail "unknown option: $1"
		;;
	esac
done

sync_file()
{
	source=$1
	destination=$2
	[ -f "$source" ] || fail "missing canonical source: $source"
	if [ "$VERIFY" -eq 1 ]; then
		[ -f "$destination" ] || fail "missing generated ABI file: $destination"
		cmp -s "$source" "$destination" ||
			fail "generated ABI file differs from canonical source: $destination"
		return
	fi
	mkdir -p -- "$(dirname -- "$destination")"
	if ! cmp -s "$source" "$destination" 2>/dev/null; then
		cp -- "$source" "$destination"
	fi
}

# Write or compare one generated header. Its text arrives on standard input
# and ends with exactly one newline.
sync_generated()
{
	destination=$1
	if [ "$VERIFY" -eq 1 ]; then
		[ -f "$destination" ] || fail "missing generated ABI file: $destination"
		cmp -s - "$destination" ||
			fail "generated ABI file differs from identity.env: $destination"
		return
	fi
	content=$(cat)
	mkdir -p -- "$(dirname -- "$destination")"
	if ! printf '%s\n' "$content" | cmp -s - "$destination" 2>/dev/null; then
		printf '%s\n' "$content" > "$destination"
	fi
}

[ -r "$IDENTITY_PATH" ] || fail "missing ABI identity: $IDENTITY_PATH"
[ -r "$PUBLIC_IDENTITY_PATH" ] ||
	fail "missing public ABI identity: $PUBLIC_IDENTITY_PATH"
# The verifier requires each identity.env to name a version and the
# fingerprint derived from its domain's current declarations.
"$ABI_DIR/verify-declarations.py"
# Both files are tracked project data containing simple shell assignments.
# shellcheck disable=SC1090
. "$IDENTITY_PATH"
# shellcheck disable=SC1090
. "$PUBLIC_IDENTITY_PATH"

# Every replayed kernel carries this header byte for byte, so its text,
# including the comment, changes only together with an ABI-changing topic.
bridge_identity_header()
{
	cat <<EOF
/* SPDX-License-Identifier: GPL-2.0-or-later */
/* Generated values are owned by kernel/common/abi/identity.env. */
#ifndef UML_DARWIN_ABI_IDENTITY_H
#define UML_DARWIN_ABI_IDENTITY_H

#define DARWIN_UML_ABI_VERSION ${DARWIN_UML_ABI_VERSION}U
#define DARWIN_UML_ABI_FINGERPRINT ${DARWIN_UML_ABI_FINGERPRINT}ULL

#endif
EOF
}

public_identity_header()
{
	cat <<EOF
/* SPDX-License-Identifier: GPL-2.0-or-later */
/* Generated by kernel/common/abi/sync.sh from darwin/api/abi/identity.env. */
#ifndef UML_EMULATOR_ABI_IDENTITY_H
#define UML_EMULATOR_ABI_IDENTITY_H

#define UML_EMULATOR_ABI_VERSION ${UML_EMULATOR_ABI_VERSION}U
#define UML_EMULATOR_ABI_FINGERPRINT ${UML_EMULATOR_ABI_FINGERPRINT}ULL

#endif
EOF
}

public_identity_header | sync_generated "$PUBLIC_IDENTITY_HEADER"
sync_file "$ABI_DIR/darwin_uml_abi.h" "$HOST_DIR/uml_darwin_abi.h"
bridge_identity_header | sync_generated "$HOST_DIR/uml_darwin_abi_identity.h"
sync_file "$ABI_DIR/darwin_uml_cpu.h" "$HOST_DIR/uml_darwin_cpu.h"
sync_file "$ABI_DIR/darwin_uml_host.h" "$HOST_DIR/uml_darwin_host.h"
sync_file "$ABI_DIR/darwin_uml_memory.h" "$HOST_DIR/uml_darwin_memory.h"
sync_file "$ABI_DIR/darwin_uml_network.h" "$HOST_DIR/uml_darwin_network.h"
sync_file "$ABI_DIR/darwin_uml_bridge.h" "$HOST_DIR/uml_darwin_bridge.h"
sync_file "$ABI_DIR/uml_tlb_sync_ranges.h" "$HOST_DIR/uml/tlb_sync_ranges.h"

if [ -n "$KERNEL_SOURCE" ]; then
	[ -d "$KERNEL_SOURCE" ] || fail "kernel source is not a directory: $KERNEL_SOURCE"
	sync_file "$ABI_DIR/darwin_uml_abi.h" \
		"$KERNEL_SOURCE/arch/um/os-Darwin/uml_darwin_abi.h"
	bridge_identity_header |
		sync_generated "$KERNEL_SOURCE/arch/um/os-Darwin/uml_darwin_abi_identity.h"
	sync_file "$ABI_DIR/darwin_uml_cpu.h" \
		"$KERNEL_SOURCE/arch/um/os-Darwin/uml_darwin_cpu.h"
	sync_file "$ABI_DIR/darwin_uml_host.h" \
		"$KERNEL_SOURCE/arch/um/os-Darwin/uml_darwin_host.h"
	sync_file "$ABI_DIR/darwin_uml_memory.h" \
		"$KERNEL_SOURCE/arch/um/os-Darwin/uml_darwin_memory.h"
	sync_file "$ABI_DIR/darwin_uml_network.h" \
		"$KERNEL_SOURCE/arch/um/os-Darwin/uml_darwin_network.h"
	sync_file "$ABI_DIR/darwin_uml_bridge.h" \
		"$KERNEL_SOURCE/arch/um/os-Darwin/uml_darwin_bridge.h"
	sync_file "$ABI_DIR/uml_tlb_sync_ranges.h" \
		"$KERNEL_SOURCE/arch/um/include/asm/tlb_sync_ranges.h"
fi
